SELECT c.COLUMN_ID AS row_id, c.ACTIVE_FLAG AS active_flag, 'Y' AS well_formed, c.TABLE_ID AS table_id, t.CATALOG_NAME AS catalog_name, t.SCHEMA_NAME AS schema_name, t.TABLE_NAME AS table_name, c.COLUMN_NAME AS column_name, c.DATA_TYPE AS data_type, c.COLUMN_POSITION AS column_position, c.IS_NULLABLE AS is_nullable FROM CFG_COLUMNS c JOIN CFG_TABLES t ON t.TABLE_ID=c.TABLE_ID ORDER BY 1
